#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

void add(int &a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    if (a < 0) a += MOD;
}

int power_mod(int base, int exponent) {
    int result = 1;
    while (exponent) {
        if (exponent & 1)
            result = static_cast<int>(1LL * result * base % MOD);
        base = static_cast<int>(1LL * base * base % MOD);
        exponent >>= 1;
    }
    return result;
}

int main() {
    int n, k;
    scanf("%d%d", &n, &k);

    vector<int> mu(k + 1), primes;
    vector<bool> composite(k + 1);
    mu[1] = 1;

    for (int i = 2; i <= k; ++i) {
        if (!composite[i]) {
            primes.push_back(i);
            mu[i] = -1;
        }
        for (int p : primes) {
            if (p > k / i) break;
            int x = i * p;
            composite[x] = true;
            if (i % p == 0) {
                mu[x] = 0;
                break;
            }
            mu[x] = -mu[i];
        }
    }

    vector<int> powers(k + 1);
    for (int i = 0; i <= k; ++i)
        powers[i] = power_mod(i, n);

    vector<int> sums(k + 1);
    for (int d = 1; d <= k; ++d) {
        if (mu[d] == 0) continue;
        for (int i = d, q = 1; i <= k; i += d, ++q)
            add(sums[i], mu[d] * powers[q]);
    }

    int answer = 0;
    for (int i = 1; i <= k; ++i)
        add(answer, sums[i] ^ i);

    printf("%d\n", answer);
    return 0;
}

