    if (a < 0) a += MOD;
}

int power(int base, int exponent) {
    int result = 1;
    while (exponent) {
        if (exponent & 1)
            result = static_cast<long long>(result) * base % MOD;
        base = static_cast<long long>(base) * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    int n, k;
    scanf("%d%d", &n, &k);

    vector<int> leastPrime(k + 1), primes;
    for (int i = 2; i <= k; ++i) {
        if (leastPrime[i] == 0) {
            leastPrime[i] = i;
            primes.push_back(i);
        }
        for (int p : primes) {
            if (p > leastPrime[i] || 1LL * i * p > k) break;
            leastPrime[i * p] = p;
        }
    }

    int answer = 0, temp = 0;
    vector<pair<int, bool>> divisors;
    divisors.reserve(128);

    for (int i = 1; i <= k; ++i) {
        divisors.clear();
        divisors.emplace_back(1, false);

        int x = i;
        while (x > 1) {
            int p = leastPrime[x];
            int currentSize = divisors.size();
            for (int j = 0; j < currentSize; ++j)
                divisors.emplace_back(divisors[j].first * p,
                                      !divisors[j].second);
            while (x % p == 0) x /= p;
        }

        for (size_t j = 1; j < divisors.size(); ++j) {
            int d = divisors[j].first;
            int previous = power((i - 1) / d, n);
            int current = power(i / d, n);

            if (divisors[j].second) {
                add(temp, -previous);
                add(temp, current);
            } else {
                add(temp, previous);
                add(temp, -current);
            }
        }

        int sum = power(i, n);
        add(sum, -temp);
        add(answer, sum ^ i);
    }

    printf("%d\n", answer);
    return 0;
}

